// Character widths with the semantics of glibc's wcwidth(), which is what mosh calls.

/// Column width of a code point as glibc 2.39's `wcwidth()` reports it in a UTF-8
/// locale. The data is `WCWidthTable`, generated by `scripts/gen-wcwidth.c`.
///
/// How mosh uses the result (`Emulator::print`):
///  - U+0000 is never looked up: it counts as -1;
///  - U+0020...U+007E and U+00A0...U+00FF are width 1 without a lookup
///    (`Cell.isPrintISO8859_1`);
///  - 1 and 2: a narrow or a wide character is printed;
///  - 0: a combining character, appended to the cell of the last printed character;
///  - -1: not printable, dropped (C1 leftovers, unassigned code points, and whatever
///    else the C library does not know).
public enum WCWidth {
    /// `wcwidth( ch )`: -1, 0, 1 or 2. -1 above U+10FFFF.
    public static func wcwidth(_ ch: UInt32) -> Int {
        if ch > 0x10FFFF { return -1 }
        // Find the last run that starts at or before ch.
        return WCWidthTable.starts.withUnsafeBufferPointer { starts -> Int in
            var lo = 0
            var hi = starts.count - 1
            while lo < hi {
                let mid = (lo + hi + 1) >> 1
                if starts[mid] <= ch {
                    lo = mid
                } else {
                    hi = mid - 1
                }
            }
            return Int(WCWidthTable.widths[lo])
        }
    }
}
